import base64, hashlib, io, json, subprocess, sys, tarfile
from pathlib import Path
import torch
PAYLOAD = ''
EXPECTED = '3f14eac1d219ee64e0c142fe8ec5edffef0b9110600e58a0035663828f7c5a76'
raw = base64.b64decode(PAYLOAD)
if hashlib.sha256(raw).hexdigest() != EXPECTED: raise RuntimeError('source archive hash mismatch')
if not torch.cuda.is_available(): raise RuntimeError('GPU is required')
print('GPU:', torch.cuda.get_device_name(0), flush=True)
root = Path('/kaggle/temp/product-baseline-src')
root.mkdir(parents=True, exist_ok=True)
with tarfile.open(fileobj=io.BytesIO(raw), mode='r:gz') as outer:
    for member in outer.getmembers():
        data = outer.extractfile(member).read()
        with tarfile.open(fileobj=io.BytesIO(data), mode='r:') as inner:
            inner.extractall(root, filter='data')
runtime = root / 'runtime'
out = Path('/kaggle/working/product-baselines')
out.mkdir(parents=True, exist_ok=True)
print('Source core: e2187d404284d9c7aa3ca6a8421c0a7625fedd98 workers: c4cf5de05b52ae0d4ee05612451bcbda2741868c', flush=True)
recipes = ['ticket-sorter-hinglish', 'invoice-fields', 'faq-bot-hinglish', 'review-sentiment']
for name in recipes:
    subprocess.run([sys.executable, '-I', str(root / 'experiments/recipes/validate_dataset.py'),
                    str(root / 'experiments/recipes' / name)], check=True)
models = [('Qwen/Qwen2.5-0.5B-Instruct', '7ae557604adf67be50417f59c2c2f167def9a775'),
          ('Qwen/Qwen2.5-1.5B-Instruct', '989aa7980e4cf806f80c7fef2b1adb7bc71aa306')]
for name in recipes:
    folder = root / 'experiments/recipes' / name
    for model, revision in models:
        subprocess.run([sys.executable, '-I', str(root / 'experiments/recipes/baseline.py'), str(folder),
                        '--model', model, '--revision', revision, '--device', 'cuda',
                        '--runtime-path', str(runtime), '--out', str(out)], check=True)
for p in sorted(out.glob('*.json')):
    result = json.loads(p.read_text(encoding='utf-8'))
    print('RESULT', p.name, result['examples'], result['pass_rate'], result['score'], flush=True)
